function releaseSettings(owner, repo, projectId, gitlab) {
  if (
    typeof owner !== "string" ||
    typeof repo !== "string" ||
    !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(owner) ||
    !/^[A-Za-z0-9_.-]{1,100}$/.test(repo) ||
    [".", "..", "YOUR_GITHUB_REPOSITORY"].includes(repo)
  ) {
    throw new Error("Set the exact GitHub owner and repository.");
  }
  const id = Number(projectId);
  if (typeof projectId !== "string" || !/^[1-9]\d*$/.test(projectId) || !Number.isSafeInteger(id)) {
    throw new Error("Set the numeric ID of your target GitLab project.");
  }
  if (
    typeof gitlab !== "string" ||
    gitlab.length > 2048 ||
    !/^https:\/\/(?:(?:[A-Za-z0-9-]+\.)+[A-Za-z][A-Za-z0-9-]*|(?:\d{1,3}\.){3}\d{1,3})(?::\d{1,5})?(?:\/[A-Za-z0-9_-]+)*\/?$/.test(
      gitlab,
    ) ||
    /\/api(?:\/|$)/.test(gitlab)
  ) {
    throw new Error("Set the canonical HTTPS GitLab site URL without /api/v4.");
  }
  const site = gitlab.replace(/\/$/, "");
  const reservePrefix = [
    "gh-release",
    site,
    projectId,
    owner.toLowerCase(),
    repo.toLowerCase(),
    "",
  ].join(":");
  if (reservePrefix.length + 16 > 256) {
    throw new Error(
      "The combined GitHub and GitLab configuration is too long for the release reservation key.",
    );
  }
  return { owner, repo, projectId, id, gitlab: site, reservePrefix };
}

export default ({ owner, repo, projectId, gitlab }) => ({
  config: releaseSettings(owner, repo, projectId, gitlab),
  owner,
  repo,
  projectId,
});

