export default async ({ release }, ctx) => {
  const reserved = await ctx.state.insert(release.key, {
    status: "creation_unconfirmed",
    tag: release.tag,
    releaseId: release.releaseId,
  });
  return {
    reserved,
    title: release.title,
    description: release.description,
    status: reserved ? "reserved" : "previous_creation_attempt",
  };
};

