function isIssueUrl(url, projectUrl, iid) {
  return url === projectUrl + "/-/issues/" + iid || url === projectUrl + "/issues/" + iid;
}

function confirmReleaseIssue(issue, cfg, release) {
  if (
    issue?.project_id !== cfg.id ||
    !Number.isSafeInteger(issue.iid) ||
    issue.iid < 1 ||
    issue.title !== release.title ||
    issue.description !== release.description ||
    issue.state !== "opened" ||
    !isIssueUrl(issue.web_url, cfg.projectUrl, issue.iid)
  ) {
    throw new Error(
      "GitLab did not confirm the exact issue. Check the project before repeating the write.",
    );
  }
  return {
    status: "created",
    tag: release.tag,
    projectId: cfg.projectId,
    issueNumber: issue.iid,
    issueUrl: issue.web_url,
  };
}

export default async ({ issue, config, release }, ctx) => {
  const result = confirmReleaseIssue(issue, config, release);
  await ctx.state.set(release.key, result);
  return { result };
};
